package com.portfoliv.app;
import android.content.Context;import android.webkit.*;import android.net.Uri;import java.io.*;import java.net.*;import java.util.*;import java.nio.charset.StandardCharsets;
final class AppResources {
 final Context context;final StateStore state;
 AppResources(Context c,StateStore s){context=c;state=s;}
 byte[] asset(String name) throws IOException {try(InputStream in=context.getAssets().open("app/"+name)){return read(in,2000000);}}
 static byte[] read(InputStream in,int max) throws IOException {ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buf=new byte[8192];int n;while((n=in.read(buf))!=-1){if(out.size()+n>max)throw new IOException();out.write(buf,0,n);}return out.toByteArray();}
 WebResourceResponse response(byte[] bytes,String type){return new WebResourceResponse(type,"UTF-8",new ByteArrayInputStream(bytes));}
 WebResourceResponse intercept(WebResourceRequest request){Uri url=request.getUrl();if(!"https".equals(url.getScheme())||!"portfoliv.onrender.com".equals(url.getHost())||url.getPort()!=-1&&url.getPort()!=443)return null;try{String path=url.getPath();if(path.equals("/__portfoliv_app__/bootstrap.js"))return response(("window.__pfBoot="+state.read()+";\n"+new String(asset("bootstrap.js"),StandardCharsets.UTF_8)).getBytes(StandardCharsets.UTF_8),"application/javascript");if(path.equals("/__portfoliv_app__/app.css"))return response(asset("app.css"),"text/css");String match=path+"?"+url.getQuery();String bundle=null;if(match.equals("/js/main.js?v=private5"))bundle="main.js";if(match.equals("/js/portfolio-builder.js?v=5"))bundle="portfolio-builder.js";if(match.equals("/js/career.js?v=4"))bundle="career.js";if(match.equals("/js/career-pdf.js?v=1"))bundle="career-pdf.js";if(bundle!=null)return response(asset(bundle),"application/javascript");
 if(request.isForMainFrame()&&path.equals("/")&&request.getMethod().equals("GET")){HttpURLConnection c=(HttpURLConnection)new URL(url.toString()).openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(20000);c.setReadTimeout(30000);for(Map.Entry<String,String> h:request.getRequestHeaders().entrySet())if(!h.getKey().equalsIgnoreCase("Accept-Encoding"))c.setRequestProperty(h.getKey(),h.getValue());String cookie=android.webkit.CookieManager.getInstance().getCookie("https://portfoliv.onrender.com/");if(cookie!=null)c.setRequestProperty("Cookie",cookie);if(c.getResponseCode()!=200){c.disconnect();return null;}Map<String,String> headers=new HashMap<>();for(Map.Entry<String,List<String>> h:c.getHeaderFields().entrySet())if(h.getKey()!=null&&!h.getKey().equalsIgnoreCase("Content-Length")&&!h.getKey().equalsIgnoreCase("Content-Encoding"))headers.put(h.getKey(),String.join(", ",h.getValue()));String html;try(InputStream in=c.getInputStream()){html=new String(read(in,2000000),StandardCharsets.UTF_8);}c.disconnect();if(!html.contains("<head>"))return null;html=html.replace("<head>","<head><script src=\"/__portfoliv_app__/bootstrap.js\"></script>");return new WebResourceResponse("text/html","UTF-8",200,"OK",headers,new ByteArrayInputStream(html.getBytes(StandardCharsets.UTF_8)));}}catch(Exception e){}return null;}
}
